#include<bits/stdc++.h>
#define int long long
using namespace std;

signed main(){
	int n,q,p;
	cin>>n>>q>>p;
	while(n--){
		int x,y;
		cin>>x>>y;
		int g=__gcd(x,y);
		if(x==y){
			cout<<0<<endl;
			continue;
		}
		if(x==1||y==1){
			cout<<q<<endl;
			continue;
		}
		if(g==1){
			cout<<min(q,p*2)<<endl;
		}else{
			cout<<min(q*2,p)<<endl;
		}
	}
	return 0;
}
